import{_ as e,o,c as r,a2 as n}from"./chunks/framework.DnrXFDHb.js";const _=JSON.parse('{"title":"术语表","description":"StreamMUSE 项目中使用的专业术语与缩写","frontmatter":{"title":"术语表","description":"StreamMUSE 项目中使用的专业术语与缩写"},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1773326634000}'),c={name:"reference/glossary.md"};function a(d,t,s,i,p,l){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><hr><h2 id="音乐术语" tabindex="-1">音乐术语 <a class="header-anchor" href="#音乐术语" aria-label="Permalink to &quot;音乐术语&quot;">​</a></h2><p><strong>BPM（Beats Per Minute）</strong> 每分钟拍数，衡量音乐速度。默认 120 BPM = 每秒 2 拍。</p><p><strong>Tick</strong> 系统内部的最细时间单位。默认 <code>ticks_per_beat=4</code>，即 1 tick = 1/4 拍。在 120 BPM 下，1 tick = 0.125 秒。</p><p><strong>Beat（拍）</strong> 音乐的基本节拍单位。默认 1 拍 = 4 ticks。</p><p><strong>Bar / Measure（小节）</strong> 由 <code>beats_per_bar</code> 个拍组成，默认 4 拍一小节。</p><p><strong>Count-in</strong> 正式演奏前的预备拍。StreamMUSE 中 <code>--count-in-beats N</code> 会在正式 tick=0 前空转 N 拍，只输出 metronome，不读取正式输入，不发送推理请求。</p><p><strong>Metronome</strong> 节拍器 click。当前实现默认用 MIDI channel 9（GM percussion channel 10），downbeat note=76 velocity=110，普通 beat note=77 velocity=80。</p><p><strong>Polyphony（复音）</strong> 同一时刻发出的音符数量。</p><p><strong>NOTE_ON / NOTE_OFF</strong> MIDI 事件类型。<code>NOTE_ON</code>（velocity &gt; 0）触发音符；<code>NOTE_OFF</code> 或 <code>NOTE_ON</code>（velocity = 0）释放音符。</p><p><strong>MIDI Program（乐器编号）</strong> MIDI 标准中的乐器编号（0–127），对应 General MIDI 音色集。如 0=钢琴。</p><p><strong>Velocity（力度）</strong> 音符的击键力度（0–127）。0 等效于 NOTE_OFF。</p><hr><h2 id="技术术语" tabindex="-1">技术术语 <a class="header-anchor" href="#技术术语" aria-label="Permalink to &quot;技术术语&quot;">​</a></h2><p><strong>Clean Architecture</strong> Robert C. Martin 提出的软件架构模式，将系统分为 Presentation → Application → Domain → Infrastructure，外层依赖内层，内层不依赖外层。</p><p><strong>Protocol（协议）</strong> Python 中的结构化子类型接口，通过 <code>typing.Protocol</code> 定义。StreamMUSE 中的 <code>InputSource</code>、<code>OutputSink</code>、<code>InferenceEngine</code> 均为 Protocol。</p><p><strong>Domain（领域层）</strong> 系统的核心业务规则层，不依赖 I/O 或框架。StreamMUSE 的 Domain 层包含 <code>MusicalEvent</code>、<code>Tempo</code>、<code>PlaybackScheduler</code> 等。</p><p><strong>Infrastructure（基础设施层）</strong> 系统的最外层，包含 MIDI 设备、HTTP 客户端、文件 I/O、模型适配器等具体实现。</p><p><strong>Tick=0 约定</strong> InputSource 发出的原始 <code>MusicalEvent</code> 通常使用 <code>tick=0</code>，由 Application 层根据正式时间线的 wall-clock 赋值实际 tick。</p><p><strong>Beat-tail trigger</strong> 当前实时推理触发策略：默认 <code>ticks_per_beat=4</code> 时，在 tick=3、7、11... 发送下一拍请求，<code>generation_start_tick=tick+1</code>。</p><p><strong>Latest-only inference</strong> 推理线程处理队列积压时只保留最新请求 tick，并合并被跳过请求中的 melody 增量，避免旧请求堆积。</p><p><strong>close-at-horizon</strong><code>events_to_notes()</code> 转换策略：在 <code>horizon_tick</code> 时仍未结束的音符，在该 tick 处截断，而不是丢弃。</p><p><strong>Fan-out（扇出）</strong><code>CompositeOutputSink</code> 的工作模式：将一个方法调用广播给所有子 Sink。</p><p><strong>Injection</strong> 会话开始前把已有 melody/accompaniment 历史注入 server。CLI 通过 <code>--injection-file</code> 和 <code>--injection-length</code> 支持 MIDI 文件注入。</p><hr><h2 id="系统组件术语" tabindex="-1">系统组件术语 <a class="header-anchor" href="#系统组件术语" aria-label="Permalink to &quot;系统组件术语&quot;">​</a></h2><p><strong>InferenceEngine</strong> 推理引擎接口，负责根据旋律历史生成伴奏（<code>generate_accompaniment()</code>），并可选支持 <code>inject_history()</code> / <code>clear_history()</code>。</p><p><strong>InputSource</strong> 输入源接口，通过 <code>read_events()</code> 生成器提供 <code>MusicalEvent</code> 流。</p><p><strong>OutputSink</strong> 输出 Sink 接口，接收事件、tick、统计和状态信息并处理（播放、录制、记录等）。</p><p><strong>PlaybackScheduler</strong> 线程安全的事件调度器，按 tick 安排未来事件，供 <code>_tick_loop</code> 在正确时间播放。</p><p><strong>RealTimeMusicService</strong> 系统核心三线程编排服务：<code>_input_worker</code>、<code>_tick_loop</code>、<code>_inference_worker</code>。</p><p><strong>SessionManager</strong> 会话目录管理器，负责创建带时间戳的日志目录和保存会话元数据。</p><p><strong>TimingInfo</strong> 推理时序信息 dataclass，包含请求到达、推理开始/结束、响应发送等时间戳字段。</p><hr><h2 id="缩写" tabindex="-1">缩写 <a class="header-anchor" href="#缩写" aria-label="Permalink to &quot;缩写&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>全称</th></tr></thead><tbody><tr><td>MIDI</td><td>Musical Instrument Digital Interface</td></tr><tr><td>BPM</td><td>Beats Per Minute</td></tr><tr><td>CLI</td><td>Command-Line Interface</td></tr><tr><td>API</td><td>Application Programming Interface</td></tr><tr><td>HTTP</td><td>HyperText Transfer Protocol</td></tr><tr><td>JSON</td><td>JavaScript Object Notation</td></tr><tr><td>JSONL</td><td>JSON Lines</td></tr><tr><td>GM</td><td>General MIDI</td></tr></tbody></table>',37)])])}const h=e(c,[["render",a]]);export{_ as __pageData,h as default};
